import{_ as l,C as a,o as s,c as h,j as t,a as r,E as o,b as c,w as n,a3 as g,a4 as u}from"./chunks/framework.DyX1TuK3.js";const C=JSON.parse('{"title":"Eval Iterations v1–v8","description":"","frontmatter":{},"headers":[],"relativePath":"en/eval.md","filePath":"en/eval.md"}'),m={name:"en/eval.md"};function p(b,e,f,v,y,w){const i=a("EvalChart"),d=a("Mermaid");return s(),h("div",null,[e[1]||(e[1]=t("h1",{id:"eval-iterations-v1–v8",tabindex:"-1"},[r("Eval Iterations v1–v8 "),t("a",{class:"header-anchor",href:"#eval-iterations-v1–v8","aria-label":'Permalink to "Eval Iterations v1–v8"'},"​")],-1)),e[2]||(e[2]=t("p",null,[r("No tuning by vibes: an automated harness over 45 real queries ("),t("strong",null,"LLM-as-judge"),r(" grades every query × top-5 result), every change gets scored — winners stay, losers roll back.")],-1)),o(i),e[3]||(e[3]=t("h2",{id:"architecture-extract-config-into-variables-let-eval-sweep-the-weights",tabindex:"-1"},[r("Architecture: extract config into variables, let eval sweep the weights "),t("a",{class:"header-anchor",href:"#architecture-extract-config-into-variables-let-eval-sweep-the-weights","aria-label":'Permalink to "Architecture: extract config into variables, let eval sweep the weights"'},"​")],-1)),e[4]||(e[4]=t("p",null,[r("The key move is "),t("strong",null,[r("pulling every search knob out of the code into a single data file, "),t("code",null,"search-config.json")]),r(` (hot-loaded — edit and it takes effect on the next search). Once config is data rather than hard-coded constants, the whole config becomes a "variable vector" the eval can sweep automatically — this is ADR 0004's two-stage self-eval loop.`)],-1)),(s(),c(g,null,{default:n(()=>[o(d,{id:"mermaid-14",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20CFG%5B%22search-config%20%E2%80%94%20tunable%20vars%22%5D%0A%20%20%20%20%20%20%20%20K%5B%22global%20knobs%3Cbr%2F%3Eweights.vector%20%2F%20bm25%20%2F%20hyde%3Cbr%2F%3Errf_k%20%C2%B7%20boost_scale%20%C2%B7%20min_score%22%5D%0A%20%20%20%20%20%20%20%20D%5B%2214-dim%20dimension%20weights%3Cbr%2F%3Eregion%202.0%20%C2%B7%20ip%201.8%20%C2%B7%20award%201.5%3Cbr%2F%3Ecuration%200.3%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20QER%5B%22eval-queries.json%3Cbr%2F%3E45%20real%20queries%20%2B%20qrels%22%5D%0A%0A%20%20%20%20subgraph%20S1%5B%22%E2%91%A0%20Stage%201%20%E2%80%94%20eval_search.py%20(measure)%22%5D%0A%20%20%20%20%20%20%20%20RUN%5B%22run%20real%20pipeline%20%E2%86%92%20top-k%22%5D%20--%3E%20JG%5B%22LLM-as-judge%3Cbr%2F%3Egrade%20each%20(query%20%C3%97%20film)%200%20%2F%201%20%2F%202%22%5D%0A%20%20%20%20%20%20%20%20JG%20--%3E%20CA%5B(%22judge%20cache%3Cbr%2F%3Eper%20query%C3%97film%22)%5D%0A%20%20%20%20%20%20%20%20JG%20--%3E%20RX%5B%22ranx%3Cbr%2F%3EnDCG%40k%20%C2%B7%20MAP%20%C2%B7%20MRR%20%C2%B7%20P%40k%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20S2%5B%22%E2%91%A1%20Stage%202%20%E2%80%94%20tune_search.py%22%5D%0A%20%20%20%20%20%20%20%20SAMP%5B%22pick%20a%20random%20weight%20combo%3Cbr%2F%3E(sample%20the%20tunable%20ranges)%22%5D%20--%3E%20INJ%5B%22apply%20the%20weights%2C%20run%20search%3Cbr%2F%3E(in-memory%20hot-swap%20%C2%B7%20no%20file%20write)%22%5D%0A%20%20%20%20%20%20%20%20RX%20--%3E%20SCORE%5B%22score%20this%20combo's%20nDCG%22%5D%0A%20%20%20%20%20%20%20%20SCORE%20--%3E%20CMP%7B%22better%20than%20current%3F%22%7D%0A%20%20%20%20end%0A%0A%20%20%20%20QER%20--%3E%20RUN%0A%20%20%20%20CFG%20-.%20extracted%20as%20variables%20.-%3E%20SAMP%0A%20%20%20%20INJ%20--%3E%20RUN%0A%20%20%20%20CMP%20--%3E%7Cyes%7C%20CAND%5B%22candidate.json%20%2B%20comparison%20report%22%5D%0A%20%20%20%20CMP%20--%3E%7Cno%7C%20KEEP%5B%22keep%20current%20config%22%5D%0A%20%20%20%20CAND%20--%3E%20PRO%5B%22%E2%91%A2%20Stage%203%20%E2%80%94%20human%20promote%22%5D%0A%0A%20%20%20%20classDef%20llm%20fill%3A%23f26f21%2Cstroke%3A%23d4570c%2Ccolor%3A%23000%0A%20%20%20%20classDef%20store%20fill%3A%231f1f1f%2Cstroke%3A%23f26f21%2Ccolor%3A%23efefef%0A%20%20%20%20class%20JG%20llm%0A%20%20%20%20class%20CA%2CCAND%20store%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=u('<h3 id="which-weight-variables-get-extracted" tabindex="-1">Which weight variables get extracted <a class="header-anchor" href="#which-weight-variables-get-extracted" aria-label="Permalink to &quot;Which weight variables get extracted&quot;">​</a></h3><p>Once extracted, config splits into two layers, each set differently:</p><table tabindex="0"><thead><tr><th>Layer</th><th>Variables</th><th>How they&#39;re set</th></tr></thead><tbody><tr><td><strong>Global knobs</strong> (SPACE)</td><td><code>weights.vector/bm25/hyde</code> (three recall routes), <code>tag_boost_scale</code> (overall dimension-boost multiplier), <code>rrf_k</code> (fusion constant), <code>min_display_score</code></td><td>Stage 2 <strong>random-search sweep</strong> — cartesian product over SPACE, sample N combos</td></tr><tr><td><strong>14-dim dimension weights</strong></td><td>region 2.0 · ip 1.8 · award/audience 1.5 · genre 1.0 · theme 0.7 … curation 0.3</td><td><strong>hand-tuned</strong>, rule: the more definitional/factual (region/IP/award) the higher; the more preferential (theme/emotion) the lower</td></tr></tbody></table><p>Weights boost, not filter: a unified &quot;weighted boost&quot; model with <strong>no hard filtering</strong> — each film carrying a requested tag gets <code>score += that dimension&#39;s weight × tag_boost_scale</code>, so results are never wiped empty. Dimensions with weight ≥ <code>inject_weight_threshold</code> (1.5) count as &quot;strong conditions&quot; and actively <strong>inject</strong> films carrying that tag into the candidate pool (the &quot;wildcard&quot; from the search page), guaranteeing something to rank rather than relying on recall to stumble onto them.</p><h3 id="why-the-sweep-is-affordable-the-judge-cache" tabindex="-1">Why the sweep is affordable: the judge cache <a class="header-anchor" href="#why-the-sweep-is-affordable-the-judge-cache" aria-label="Permalink to &quot;Why the sweep is affordable: the judge cache&quot;">​</a></h3><p>Sweeping N configs looks like N rounds of judging, but <strong>relevance is per (query, film), independent of config</strong> — swapping weights only <strong>reorders</strong> the same films; it never creates a new (query, film) pair. So every judged result hits the <code>judge cache</code>, and N configs cost essentially <strong>one</strong> round of judging (the expensive part). That&#39;s the precondition that makes &quot;extract config into variables and sweep&quot; viable.</p><p>Scoring uses <code>rerank=False</code> (CE reranker off): it isolates the contribution of recall + weighted ranking itself, free of reranker noise, and it&#39;s fast. Finally it <strong>never overwrites the live config</strong> — the winner only lands in <code>candidate.json</code> + a comparison report; a human (Stage 3) decides whether to promote it → echoing the <a href="/film-brain/en/self-eval">self-eval loop</a>&#39;s &quot;winners stay, losers roll back&quot; and human-in-the-loop.</p><h2 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Metric</th><th>Plainly</th><th>What 1.0 means</th></tr></thead><tbody><tr><td><strong>nDCG@5</strong></td><td>ranking quality of the top 5 — position matters, not just presence</td><td>the most relevant exactly on top</td></tr><tr><td><strong>MRR</strong></td><td>where the first relevant result lands on average (reciprocal)</td><td>rank #1 relevant for every query</td></tr><tr><td><strong>P@5</strong></td><td>share of relevant films in the top 5 — order-agnostic hit rate</td><td>all five relevant</td></tr></tbody></table><h2 id="version-overview" tabindex="-1">Version overview <a class="header-anchor" href="#version-overview" aria-label="Permalink to &quot;Version overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>Change</th><th>nDCG@5</th><th>MRR</th><th>P@5</th><th>Verdict</th></tr></thead><tbody><tr><td>v1</td><td>baseline (hybrid + RRF)</td><td>0.9307</td><td>0.925</td><td>0.86</td><td>starting point</td></tr><tr><td>v2</td><td>several gating ideas at once</td><td>0.9255</td><td>0.9167</td><td>0.84</td><td>regression — changed too much</td></tr><tr><td><strong>v3</strong></td><td>keep only the parser alias</td><td><strong>0.9512</strong></td><td>0.925</td><td><strong>0.89</strong></td><td>first big win</td></tr><tr><td>v4</td><td>+ English-domain reranker</td><td>0.9368</td><td>0.925</td><td>0.73</td><td>wrong model, precision dropped</td></tr><tr><td>v5</td><td>step-back always on</td><td>0.9350</td><td>0.925</td><td>0.85</td><td>helped vague, hurt specific</td></tr><tr><td><strong>v6</strong></td><td>step-back gated conditionally</td><td>0.9623</td><td><strong>1.000</strong></td><td>0.84</td><td>perfect MRR ⭐</td></tr><tr><td>v7</td><td>English-domain reranker, retried</td><td>0.9368</td><td>0.9417</td><td>0.79</td><td>confirmed: it&#39;s the model</td></tr><tr><td><strong>v8</strong></td><td>Chinese-domain reranker (bce)</td><td><strong>0.9625</strong></td><td>0.975</td><td><strong>0.89</strong></td><td>best balance ⭐</td></tr></tbody></table><h2 id="iteration-diary" tabindex="-1">Iteration diary <a class="header-anchor" href="#iteration-diary" aria-label="Permalink to &quot;Iteration diary&quot;">​</a></h2><details class="note"><summary>v1 — measure before touching anything</summary> Plant the yardstick: score the plain pipeline as-is — 0.9307. Optimization without a baseline is self-congratulation. </details><details class="note"><summary>v2 — greed: four ideas at once, regression</summary> Shipped four query-understanding improvements together. -0.005; three queries improved, five worsened, impossible to assign credit.<br><b class="turn">→ One variable per round, from then on.</b></details><details class="note"><summary>v3 — unbundle, keep one: first big win</summary> Kept only the keyword alias table. +0.02 → 0.9512; previously-missed signals all landed.<br><b class="turn">→ Extending the alias table is pure profit.</b></details><details class="note"><summary>v4 — first reranker: faceplant</summary> An English-domain reranker dropped nDCG and P@5 to 0.73.<br><b class="turn">→ &quot;More AI&quot; doesn&#39;t mean better; it can&#39;t read a Chinese library.</b></details><details class="note"><summary>v5 — query abstraction: helps vague, hurts specific</summary> Step-back vector helped vague queries, injected noise into specific ones. Net loss.<br><b class="turn">→ Double-edged — the question is when, not whether.</b></details><details class="note"><summary>v6 — same trick, plus a switch: perfect MRR ⭐</summary> Abstraction only when the parser finds nothing concrete. 0.9623, rank-1 correct on every query.<br><b class="turn">→ Gate the smallest possible knob.</b></details><details class="note"><summary>v7 — retry English reranker: confirmed it&#39;s the model</summary> Added context + position-aware blend — architecturally right, still 0.9368.<br><b class="turn">→ Architecture patches can&#39;t rescue the wrong model.</b></details><details class="note"><summary>v8 — Chinese-domain reranker: best balance ⭐</summary> Same API, Chinese-IR-trained bce. nDCG flat, P@5 +0.05, zero eval failures.<br><b class="turn">→ A reranker&#39;s language domain beats its architecture.</b></details><h2 id="appendix-a-thriftier-yardstick-—-the-judge-s-model-and-hardware" tabindex="-1">Appendix: a thriftier yardstick — the judge&#39;s model and hardware <a class="header-anchor" href="#appendix-a-thriftier-yardstick-—-the-judge-s-model-and-hardware" aria-label="Permalink to &quot;Appendix: a thriftier yardstick — the judge&#39;s model and hardware&quot;">​</a></h2><p>The grader was <strong>a local model throughout</strong>. Why not cloud? One round is 45 × top-5 = up to 225 gradings; eleven rounds approach 2,500 — free cloud tiers hit limits and fight the product for quota. Local judge: zero marginal cost, reruns anytime, reproducible.</p><p>v1–v8 used a larger MoE model (35B-A3B, GPU); later a smaller <strong>8B dense model on an NPU</strong> re-scored — <strong>a different judge is a different yardstick; not comparable with the table above</strong>:</p><table tabindex="0"><thead><tr><th>Round</th><th>Scope</th><th>nDCG@5</th><th>MRR</th><th>Verdict</th></tr></thead><tbody><tr><td>8B judge @ NPU (subset)</td><td>20 queries</td><td>0.9286</td><td>0.9417</td><td>small-model + NPU pipeline works</td></tr><tr><td>8B judge @ NPU (full)</td><td>45 queries</td><td>0.9233</td><td>0.9444</td><td>sustained, low-power, off the GPU</td></tr></tbody></table>',24))])}const k=l(m,[["render",p]]);export{C as __pageData,k as default};
